# WARNING: Under review - generated by LLM.

import importlib
import json
from types import SimpleNamespace

from .tiny_llm_base import (
    AgentError,
    AgentLimits,
    FinalAction,
    ToolAction,
    initial_messages,
    run_agent,
)


class FakeWorkspace:
    """Minimal Day 1 tool boundary; later days implement the real workspace."""

    def __init__(self, root):
        self.policy = SimpleNamespace(
            root=root,
            allow_writes=False,
            allowed_commands=(),
        )
        self.available_tools = frozenset({"read_file"})
        self.cancellation = None
        self.session_log = None
        self.modified_files = set()
        self.uncertain_modified_files = set()
        self.retained_recovery_files = set()
        self.command_side_effects_untracked = False
        self.command_cleanup_incomplete = False
        self.executed = []

    def execute(self, action):
        self.executed.append(action)
        return "README contents"


def install_loop_fakes(monkeypatch):
    """Keep the Day 1 loop exercise independent of Days 2 and 3."""

    loop = importlib.import_module(run_agent.__module__)

    def parse_action(response, available_tools=None):
        try:
            raw = json.loads(response)
        except json.JSONDecodeError as error:
            raise AgentError("response is not valid JSON") from error
        if set(raw) == {"final"} and isinstance(raw["final"], str):
            return FinalAction(raw["final"])
        if raw.get("tool") != "read_file":
            raise AgentError(f"unknown tool: {raw.get('tool')}")
        if set(raw) != {"tool", "path"} or not isinstance(raw["path"], str):
            raise AgentError("invalid read_file action")
        if available_tools is not None and "read_file" not in available_tools:
            raise AgentError("tool is not enabled: read_file")
        return ToolAction("read_file", {"path": raw["path"]})

    def append_tool_result(messages, response, result):
        return [
            *messages,
            {"role": "assistant", "content": response},
            {"role": "tool", "content": result},
        ]

    package = loop.__package__
    protocol = importlib.import_module(f"{package}.protocol")
    context = importlib.import_module(f"{package}.context")
    monkeypatch.setattr(protocol, "build_system_prompt", lambda _workspace: "tools")
    monkeypatch.setattr(protocol, "parse_action", parse_action)
    monkeypatch.setattr(context, "append_tool_result", append_tool_result)
    monkeypatch.setattr(
        loop,
        "build_system_prompt",
        lambda _workspace: "tools",
        raising=False,
    )
    monkeypatch.setattr(loop, "parse_action", parse_action, raising=False)
    monkeypatch.setattr(
        loop,
        "append_tool_result",
        append_tool_result,
        raising=False,
    )


def test_task_1_initial_messages_preserve_the_task():
    messages = initial_messages("inspect the project", "system instructions")

    assert messages == [
        {"role": "system", "content": "system instructions"},
        {"role": "user", "content": "inspect the project"},
    ]


def test_task_1_rejects_an_empty_task():
    try:
        initial_messages("   ", "system instructions")
    except ValueError as error:
        assert "must not be empty" in str(error)
    else:
        assert False, "expected an empty task to be rejected"


def test_task_2_executes_a_tool_appends_its_result_and_finishes(tmp_path, monkeypatch):
    install_loop_fakes(monkeypatch)
    workspace = FakeWorkspace(tmp_path)
    seen_messages = []
    responses = iter(
        [
            '{"tool":"read_file","path":"README.md"}',
            '{"final":"inspected README"}',
        ]
    )

    def generate(messages):
        seen_messages.append(messages)
        return next(responses)

    result = run_agent("inspect the project", generate, workspace)

    assert result.completed
    assert result.reason == "completed"
    assert result.final == "inspected README"
    assert workspace.executed == [ToolAction("read_file", {"path": "README.md"})]
    assert seen_messages[1][-1] == {
        "role": "tool",
        "content": "README contents",
    }


def test_task_3_returns_invalid_and_unknown_actions_to_the_model(tmp_path, monkeypatch):
    install_loop_fakes(monkeypatch)
    workspace = FakeWorkspace(tmp_path)
    seen_messages = []
    responses = iter(
        [
            "not json",
            '{"tool":"run_shell","argv":["rm","-rf","."]}',
            '{"final":"recovered"}',
        ]
    )

    def generate(messages):
        seen_messages.append(messages)
        return next(responses)

    result = run_agent("inspect the project", generate, workspace)

    assert result.completed
    assert workspace.executed == []
    assert [event.action for event in result.events[:2]] == [None, None]
    assert all(event.result.startswith("error:") for event in result.events[:2])
    assert seen_messages[1][-1]["content"].startswith("error:")
    assert seen_messages[2][-1]["content"].startswith("error:")


def test_task_4_stops_at_the_step_budget(tmp_path, monkeypatch):
    install_loop_fakes(monkeypatch)
    workspace = FakeWorkspace(tmp_path)

    result = run_agent(
        "inspect the project",
        lambda _messages: '{"tool":"read_file","path":"README.md"}',
        workspace,
        AgentLimits(max_steps=2, max_identical_actions=3),
    )

    assert not result.completed
    assert result.reason == "step_limit"
    assert len(result.events) == 2
    assert len(workspace.executed) == 2
